  'address-line1': 'street',
  'address-level2': 'city',
  'address-level1': 'state',
  'postal-code': 'zip',
  'country-name': 'country',
  'country': 'country',
  organization: 'company',
  'organization-title': 'job_title',
  username: 'username',
  'current-password': 'password',
  'new-password': 'password',
  url: 'url',
  'cc-number': 'text',
};

