  switch ((desc.type ?? '').toLowerCase()) {
    case 'email':
      return 'email';
    case 'tel':
      return 'phone';
    case 'url':
      return 'url';
    case 'number':
      return 'number';
    case 'date':
    case 'datetime-local':
    case 'month':
    case 'time':
    case 'week':
      return 'date';
    case 'color':
      return 'color';
    case 'checkbox':
      return 'checkbox';
    case 'radio':
      return 'radio';
    case 'range':
      return 'range';
    case 'password':
      return 'password';
    default:
      return undefined;
  }
